awk '
{
  s = $0
  while (match(s, /<[^>]+>/)) {
    tag = substr(s, RSTART+1, RLENGTH-2)
    s = substr(s, RSTART + RLENGTH)
    if (tag ~ /^\?/ || tag ~ /^!/) continue
    if (tag ~ /^\//) { name = tag; sub(/^\//, "", name); close_count[name]++ }
    else if (tag ~ /\/$/) { }
    else { name = tag; sub(/[ \t].*$/, "", name); open_count[name]++ }
  }
}
END {
  bad = 0
  for (t in open_count) {
    c = close_count[t] + 0
    if (open_count[t] != c) { print "MISMATCH", t, open_count[t], c; bad = 1 }
  }
  for (t in close_count) if (!(t in open_count)) { print "EXTRA_CLOSE", t; bad = 1 }
  print bad ? "BAD" : "WELL_FORMED"
}' /work/SystemContext.svg

